refused_program.body:
set -u
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' 0

if ! git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  git merge --no-commit {upstream_remote}/{upstream_branch} >/dev/null 2>&1 || true
fi

if ! git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  echo "merge with {upstream_remote}/{upstream_branch} did not start" >&2
  exit 1
fi

if git ls-files -u -- deps.lock | grep -q .; then
  base=$(git merge-base HEAD {upstream_remote}/{upstream_branch})
  git show "$base:deps.lock" > "$tmp/base"
  git show "HEAD:deps.lock" > "$tmp/ours"
  git show "{upstream_remote}/{upstream_branch}:deps.lock" > "$tmp/theirs"
  git diff --no-index -U0 "$tmp/base" "$tmp/ours" > "$tmp/local.diff" 2>/dev/null || true

  awk -v oursfile="$tmp/ours" -v difffile="$tmp/local.diff" -v theirsfile="$tmp/theirs" '
    function flush(   i) {
      if (inh && !hasminus && nadd > 0) {
        ngroup++
        gstart[ngroup] = startline
        gcount[ngroup] = nadd
        for (i = 1; i <= nadd; i++) gline[ngroup, i] = adds[i]
      }
      nadd = 0
      hasminus = 0
    }
    BEGIN {
      while ((getline l < oursfile) > 0) ours[++nours] = l
      while ((getline l < difffile) > 0) dif[++ndif] = l
      while ((getline l < theirsfile) > 0) theirs[++ntheirs] = l

      inh = 0
      hasminus = 0
      nadd = 0
      ngroup = 0
      for (i = 1; i <= ndif; i++) {
        line = dif[i]
        if (line ~ /^@@ /) {
          flush()
          inh = 1
          rest = substr(line, index(line, "+") + 1)
          sub(/[ ,].*$/, "", rest)
          startline = rest + 0
          continue
        }
        if (!inh) continue
        c = substr(line, 1, 1)
        if (c == "-") hasminus = 1
        else if (c == "+") { nadd++; adds[nadd] = substr(line, 2) }
      }
      flush()

      for (i = 1; i <= ntheirs; i++) in_theirs[theirs[i]] = 1
      for (i = 0; i <= ntheirs; i++) npend[i] = 0

      cursor = 0
      for (g = 1; g <= ngroup; g++) {
        pos = 0
        for (a = gstart[g] - 1; a >= 1; a--) {
          if (!(ours[a] in in_theirs)) continue
          found = 0
          for (i = cursor + 1; i <= ntheirs; i++) {
            if (theirs[i] == ours[a]) { pos = i; found = 1; break }
          }
          if (!found) {
            for (i = 1; i <= ntheirs; i++) {
              if (theirs[i] == ours[a]) { pos = i; found = 1; break }
            }
          }
          if (found) break
        }
        for (j = 1; j <= gcount[g]; j++) {
          l = gline[g, j]
          if ((l in in_theirs) || (l in emitted)) continue
          npend[pos]++
          pend[pos, npend[pos]] = l
          emitted[l] = 1
        }
        cursor = pos
      }

      for (i = 0; i <= ntheirs; i++) {
        if (i > 0) print theirs[i]
        for (j = 1; j <= npend[i]; j++) print pend[i, j]
      }
    }
  ' > "$tmp/merged"

  cat "$tmp/merged" > deps.lock
  git add deps.lock
fi

git commit --no-edit

postconditions.probe:
base=$(git merge-base HEAD^1 HEAD^2) &&
git diff --no-color -U0 "$base" HEAD^1 -- deps.lock |
awk '/^@@ /{ if (in_h && !minus && n) for (i=1;i<=n;i++) print add[i]; in_h=1; minus=0; n=0; next }
     in_h && /^-/ { minus=1; next }
     in_h && /^\+/ { add[++n] = substr($0,2); next }
     END { if (in_h && !minus && n) for (i=1;i<=n;i++) print add[i] }' |
while IFS= read -r l; do grep -Fxq -- "$l" deps.lock || exit 1; done
